<?php
require dirname(__DIR__).'/vendor/autoload.php';
use app\services\CatalogProperties as P;
use app\services\CatalogSize as S;
use app\services\CatalogLegacyPreview as L;
use app\services\CatalogPropertyAccess as A;
function propertyCheck($v,$m){if(!$v)throw new RuntimeException($m);}
function propertyReject(callable$f,string$m){try{$f();}catch(InvalidArgumentException|RuntimeException$e){return;}throw new RuntimeException('Not rejected: '.$m);}
$known=static fn($v)=>['state'=>'known','verification'=>'confirmed','value'=>$v,'source_ref'=>'Документ изготовителя, стр. 1'];
$empty=P::normalize(['type'=>'tyre_solid']);
propertyCheck(count($empty['issues'])>0,'Incomplete drafts allowed');
propertyReject(fn()=>P::normalize(['type'=>'tyre_solid','values'=>['inflation_pressure_kpa'=>$known('800')]]),'Solid pressure');
propertyReject(fn()=>P::normalize(['type'=>'tyre_pneumatic','values'=>['tire_size'=>['state'=>'not_applicable']]]),'Required not applicable');
propertyReject(fn()=>P::normalize(['type'=>'tyre_pneumatic','values'=>['construction'=>$known(['other-property-option'])]]),'Foreign option');
propertyReject(fn()=>P::normalize(['type'=>'tyre_solid','values'=>['tire_type'=>$known(['pneumatic'])]]),'Wrong type');
propertyReject(fn()=>P::normalize(['values'=>['brand'=>$known('EKKA')]]),'Duplicate brand source');
propertyReject(fn()=>P::normalize(['values'=>['weight_kg'=>$known('1e3')]]),'Scientific notation');
$zero=P::normalize(['type'=>'rim','values'=>['offset_mm'=>$known('0')]]);
propertyCheck($zero['values']['offset_mm']['value']==='0','Zero ET');
propertyCheck(P::normalize(['type'=>'rim','values'=>['offset_mm'=>$known('-30')]])['values']['offset_mm']['value']==='-30','Negative ET');
propertyCheck(P::normalize(['values'=>['non_marking'=>$known('0')]])['values']['non_marking']['value']==='0','False distinct from unknown');
propertyCheck(P::normalize([])['values']['non_marking']['state']==='unknown','Unknown distinct from false');
propertyReject(fn()=>P::normalize(['values'=>['weight_kg'=>['state'=>'known','value'=>'10','verification'=>'confirmed']]]),'Confirmed needs source');
propertyReject(fn()=>P::normalize(['values'=>['weight_kg'=>['state'=>'unknown','value'=>'10']]]),'Unknown cannot retain payload');
propertyCheck(P::normalize(['values'=>['barcode'=>$known('4006381333931')]])['values']['barcode']['value']==='4006381333931','Barcode checksum');
propertyReject(fn()=>P::normalize(['values'=>['barcode'=>$known('4006381333932')]]),'Wrong barcode checksum');
propertyCheck(S::normalize(' 33х12 - 20 ')==='33x12-20','Lexical normalization');
$relation=['size'=>'33x12-20','role'=>'equivalent','verification'=>'confirmed','source_ref'=>'Владелец, конкретный SKU','conditions'=>''];
propertyCheck(S::matches('33х12-20','12-16.5',[$relation]),'Confirmed equivalent matches');
propertyCheck(!S::matches('33x12-20','12-16.5',[]),'No global equivalence');
propertyCheck(!S::matches('33x12-20','12-16.5',[array_replace($relation,['verification'=>'candidate'])]),'Candidates excluded');
propertyCheck(!S::matches('33x12-20','12-16.5',[array_replace($relation,['role'=>'compatible'])]),'Compatibility not equivalence');
propertyCheck(!S::matches('33x12-20','12-16.5',[array_replace($relation,['conditions'=>'Только диск A'])]),'Conditional relation excluded without context');
propertyCheck(S::matches('33x12-20','12-16.5',[array_replace($relation,['conditions'=>'Только диск A'])],['Только диск A']),'Explicit condition');
propertyReject(fn()=>S::relations('12-16.5',[array_replace($relation,['size'=>'12-16.5'])]),'Self relation');
propertyReject(fn()=>S::relations('12-16.5',[$relation,$relation]),'Duplicate relation');
propertyReject(fn()=>S::relations('12-16.5',[array_replace($relation,['source_ref'=>''])]),'Equivalent needs evidence');
$p=['id'=>357,'sku'=>'IT000007251','name'=>'Колесо цельнолитое в сборе с диском','category_id'=>9,'model'=>'WHEELS STANDARD'];
$preview=L::forProduct($p,[['attribute_id'=>4,'attribute_text'=>'12-16.5'],['attribute_id'=>7,'attribute_text'=>'16.5'],['attribute_id'=>61,'attribute_text'=>'цельнолитые'],['attribute_id'=>67,'attribute_text'=>'33x12-20']],[['attr_group_id'=>2,'value'=>'33x12-20']]);
propertyCheck($preview['proposed']['values']['rim_diameter_in']['value']==='16.5','Alternative must not change diameter');
propertyCheck($preview['proposed']['sizes'][0]['verification']==='confirmed'&&!$preview['warnings'],'User example is specific approved relation');
$p['sku']='ANOTHER';propertyCheck(L::forProduct($p,[['attribute_id'=>4,'attribute_text'=>'12-16.5'],['attribute_id'=>67,'attribute_text'=>'33x12-20']])['proposed']['sizes'][0]['verification']==='legacy_unverified','No confirmation inherited by another SKU');
propertyReject(fn()=>A::check(['user'=>['role'=>'manager']],'GET'),'Admin authorization');
propertyReject(fn()=>A::check(['user'=>['role'=>'admin'],'catalog_properties_csrf'=>'abc'],'POST','wrong'),'CSRF');
A::check(['user'=>['role'=>'admin'],'catalog_properties_csrf'=>'abc'],'POST','abc');
$mark=['raw_marking'=>'152/148 L/M','load_single'=>null,'load_dual'=>null,'speed_symbol'=>null,'operating_mode'=>'manufacturer_other','verification'=>'legacy_unverified','source_ref'=>'legacy'];
propertyCheck(P::normalize(['ratings'=>[$mark]])['ratings'][0]['raw_marking']==='152/148 L/M','Compound marking lossless');
propertyReject(fn()=>P::normalize(['ratings'=>[array_replace($mark,['verification'=>'confirmed'])]]),'Do not confirm incomplete compound rating');
echo "Catalogue foundation validation, applicability, sizes, indexes, authorization and CSRF OK\n";
